package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@RestController @RequestMapping("/api/stores/{storeId}")
public class InventoryOperationsController {
 private final StoreAccess access;private final ProductRepository products;private final StockMovementRepository movements;private final StockBatchService batches;private final OrderPlanRepository plans;private final StoreOperationSettingsRepository settings;
 public InventoryOperationsController(StoreAccess access,ProductRepository products,StockMovementRepository movements,StockBatchService batches,OrderPlanRepository plans,StoreOperationSettingsRepository settings){this.access=access;this.products=products;this.movements=movements;this.batches=batches;this.plans=plans;this.settings=settings;}
 public record Detail(String barcode,String category,String specification,int targetStock,boolean owner){}
 public record Metadata(String category,String specification,int targetStock){}
 public record Change(int quantity,int expectedStock,String reason,Long batchId,Long batchRevision,String clientKey){}
 public record Movement(long id,String barcode,String name,String type,int before,int after,String actor,String at,String reason,Long batchId){}
 public record Recommendation(String barcode,String name,int stock,int minimum,int target,int quantity){}
 public record PlanLine(String barcode,int quantity,int expectedStock,int expectedTarget){}
 public record PlanRequest(String clientKey,List<PlanLine> items){}
 public record SavedPlan(long id,String actor,String createdAt,List<PlanItem> items,String status,long revision,String orderedAt){}
 public record PlanItem(String barcode,String name,int stock,int target,int quantity,int received){}
 private Product product(Store store,String barcode){return products.findByStoreAndBarcode(store,barcode).filter(p->!p.isDeleted()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"등록된 상품을 찾을 수 없어요"));}
 private static String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.toString().getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static void key(String key){if(key==null||!key.matches("[A-Za-z0-9_-]{8,80}"))throw new ApiException(HttpStatus.BAD_REQUEST,"저장 요청을 확인해주세요");}
 private boolean owner(Account a,Store s){return s.getOwner().getId().equals(a.getId());}
 @GetMapping("/inventory-capabilities") public Map<String,Boolean> capabilities(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){return Map.of("owner",owner(a,access.requireMember(a,storeId)),"deleteProducts",access.canInventory(a,storeId,StoreAccess.InventoryPermission.DELETE_PRODUCTS),"adjustStock",access.canInventory(a,storeId,StoreAccess.InventoryPermission.ADJUST_STOCK),"saveOrderPlans",access.canInventory(a,storeId,StoreAccess.InventoryPermission.SAVE_ORDER_PLANS));}
 @GetMapping("/products/{barcode}/details") @Transactional(readOnly=true) public Detail detail(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable String barcode){Store s=access.requireMember(a,storeId);Product p=product(s,barcode);return new Detail(barcode,p.getCategory(),p.getSpecification(),p.getTargetStock(),owner(a,s));}
 @PutMapping("/products/{barcode}/details") @Transactional public Detail metadata(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable String barcode,@RequestBody Metadata r){Store s=access.requireMember(a,storeId);batches.lock(s);Product p=product(s,barcode);if(r.category()==null||r.category().trim().length()>20||r.specification()!=null&&r.specification().length()>100||r.targetStock()<0||r.targetStock()>1000000)throw new ApiException(HttpStatus.BAD_REQUEST,"분류·규격·목표 재고를 확인해주세요");if(!owner(a,s)&&r.targetStock()!=p.getTargetStock())throw new ApiException(HttpStatus.FORBIDDEN,"목표 재고는 사장님이 설정해요");p.metadata(r.category().trim(),r.specification()==null?null:r.specification().trim(),r.targetStock());return detail(a,storeId,barcode);}
 @PostMapping("/products/{barcode}/outbound") @Transactional public Movement outbound(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable String barcode,@RequestBody Change r){return change(a,storeId,barcode,r,false);}
 @PostMapping("/products/{barcode}/adjustment") @Transactional public Movement adjustment(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable String barcode,@RequestBody Change r){access.requireInventory(a,storeId,StoreAccess.InventoryPermission.ADJUST_STOCK);return change(a,storeId,barcode,r,true);}
 private Movement change(Account a,Long storeId,String barcode,Change r,boolean adjust){Store s=access.requireMember(a,storeId);batches.lock(s);Product p=product(s,barcode);key(r.clientKey());if(r.reason()==null||r.reason().isBlank()||r.reason().length()>300)throw new ApiException(HttpStatus.BAD_REQUEST,"처리 사유를 입력해주세요");String fingerprint=hash((adjust?"ADJUST":"OUT")+r.toString());var prior=movements.findByProductAndClientKey(p,r.clientKey());if(prior.isPresent()){if(!fingerprint.equals(prior.get().getFingerprint())||!prior.get().getAccount().getId().equals(a.getId()))throw new ApiException(HttpStatus.CONFLICT,"같은 요청의 처리 내용이 달라요");return view(prior.get());}if(p.getStock()!=r.expectedStock())throw new ApiException(HttpStatus.CONFLICT,"재고가 변경됐어요. 다시 조회해주세요");if(r.quantity()<0||r.quantity()>1000000||!adjust&&r.quantity()==0||!adjust&&r.quantity()>p.getStock())throw new ApiException(HttpStatus.BAD_REQUEST,"출고·조정 수량을 확인해주세요. 현재 재고보다 많이 출고할 수 없어요");int before=p.getStock();if(adjust)batches.adjust(p,r.quantity());else if(r.batchId()!=null){if(r.batchRevision()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"입고 묶음을 다시 선택해주세요");var selected=batches.list(p).stream().filter(b->Objects.equals(b.getId(),r.batchId())).findFirst().orElse(null);if(selected==null&&r.batchId()!=0)throw new ApiException(HttpStatus.CONFLICT,"입고 묶음이 변경됐어요");int quantity=selected==null?p.getStock():selected.getQuantity();LocalDate expiry=selected==null?p.getExpiry():selected.getExpiry();if(quantity<r.quantity())throw new ApiException(HttpStatus.BAD_REQUEST,"선택한 묶음의 재고보다 출고량이 많아요");batches.update(p,r.batchId(),r.batchRevision(),quantity-r.quantity(),expiry);}else batches.adjust(p,p.getStock()-r.quantity());StockMovement m=new StockMovement(p,a,adjust?MovementType.ADJUST:MovementType.OUT,before,p.getStock());m.describe(r.reason().trim(),r.clientKey(),fingerprint,r.batchId());return view(movements.save(m));}
 private Movement view(StockMovement m){return new Movement(m.getId(),m.getProduct().getBarcode(),m.getProduct().getName(),m.getType().name(),m.getBeforeStock(),m.getAfterStock(),m.getAccount().getName(),m.getCreatedAt().toString(),m.getReason(),m.getBatchId());}
 @GetMapping("/inventory-history") @Transactional(readOnly=true) public List<Movement> history(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@RequestParam(required=false)String barcode,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(defaultValue="0")int page){access.requireMember(a,storeId);LocalDate end=to==null?LocalDate.now():to,start=from==null?end.minusDays(30):from;if(start.isAfter(end)||java.time.temporal.ChronoUnit.DAYS.between(start,end)>366||page<0||page>10000)throw new ApiException(HttpStatus.BAD_REQUEST,"조회 기간은 최대 1년으로 지정해주세요");return movements.history(storeId,barcode==null||barcode.isBlank()?null:barcode,start.atStartOfDay(),end.plusDays(1).atStartOfDay(),org.springframework.data.domain.PageRequest.of(page,50)).stream().map(this::view).toList();}
 private int target(Product p,Store s){int min=p.getMinStock()>0?p.getMinStock():settings.findById(s.getId()).map(StoreOperationSettings::getLowStockThresholdCount).orElse(3);return p.getTargetStock()>0?p.getTargetStock():Math.min(1000000,Math.max(1,min*3));}
 @GetMapping("/order-recommendations") @Transactional(readOnly=true) public List<Recommendation> recommendations(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){Store s=access.requireInventory(a,storeId,StoreAccess.InventoryPermission.SAVE_ORDER_PLANS);return products.findByStoreOrderByIdAsc(s).stream().filter(p->!p.isDeleted()).map(p->{int min=p.getMinStock()>0?p.getMinStock():settings.findById(storeId).map(StoreOperationSettings::getLowStockThresholdCount).orElse(3),target=target(p,s);return new Recommendation(p.getBarcode(),p.getName(),p.getStock(),min,target,Math.max(0,target-p.getStock()));}).filter(r->r.quantity()>0).toList();}
 public static SavedPlan planView(OrderPlan p){return new SavedPlan(p.getId(),p.getActor(),p.getCreatedAt().toString(),p.getLines().stream().map(l->new PlanItem(l.getBarcode(),l.getName(),l.getStock(),l.getTarget(),l.getQuantity(),l.getReceived())).toList(),p.getStatus(),p.getRevision(),p.getOrderedAt()==null?null:p.getOrderedAt().toString());}
 @GetMapping("/order-plans") @Transactional(readOnly=true) public List<SavedPlan> plans(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){return plans.findTop50ByStoreOrderByIdDesc(access.requireMember(a,storeId)).stream().map(InventoryOperationsController::planView).toList();}
 @PostMapping("/order-plans") @Transactional public SavedPlan plan(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@RequestBody PlanRequest r){Store s=access.requireInventory(a,storeId,StoreAccess.InventoryPermission.SAVE_ORDER_PLANS);batches.lock(s);key(r.clientKey());if(r.items()==null||r.items().isEmpty()||r.items().size()>100)throw new ApiException(HttpStatus.BAD_REQUEST,"발주할 상품을 1~100개 선택해주세요");String fingerprint=hash(r.items());var existing=plans.findByStoreAndClientKey(s,r.clientKey());if(existing.isPresent()){if(!existing.get().getFingerprint().equals(fingerprint)||!existing.get().getActorId().equals(a.getId()))throw new ApiException(HttpStatus.CONFLICT,"발주 계획 내용이 달라요");return planView(existing.get());}Set<String> seen=new HashSet<>();OrderPlan plan=new OrderPlan(s,a,r.clientKey(),fingerprint);for(var line:r.items()){Product p=product(s,line.barcode());int target=target(p,s);if(!seen.add(line.barcode())||line.quantity()<1||line.quantity()>1000000)throw new ApiException(HttpStatus.BAD_REQUEST,"발주 수량과 상품 중복을 확인해주세요");if(line.expectedStock()!=p.getStock()||line.expectedTarget()!=target)throw new ApiException(HttpStatus.CONFLICT,"재고 또는 목표 재고가 변경됐어요. 추천을 다시 조회해주세요");plan.add(p.getBarcode(),p.getName(),p.getStock(),target,line.quantity());}return planView(plans.save(plan));}
}
